import json,sys
def tokenize(text): return [w.casefold() for w in text.split()]
def count_words(tokens):
 d={}
 for w in tokens: d[w]=d.get(w,0)+1
 return {"total":len(tokens),"counts":dict(sorted(d.items()))}
if __name__=="__main__": print(json.dumps(count_words(tokenize(open(sys.argv[1],encoding="utf-8").read())),sort_keys=True))
